package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Collection;
import java.util.Collections;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.List;
import java.util.TimeZone;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for TimeSeries.createCopy(RegularTimePeriod, RegularTimePeriod).
 * Note: The provided source code contains a 'if (true)' block which forces emptyRange = true.
 * These tests are designed to cover the logic as provided in the snippet.
 */
public class TimeSeries_createCopy_TriageGen1Test {

    private TimeSeries series;
    private RegularTimePeriod startPeriod;
    private RegularTimePeriod endPeriod;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        startPeriod = new SecondRevised(new GregorianCalendar(2023, 0, 1, 10, 0, 0));
        endPeriod = new SecondRevised(new GregorianCalendar(2023, 0, 1, 11, 0, 0));

        // Adding some data to the series
        series.add(startPeriod, 10.0);
        series.add(endPeriod, 20.0);
    }

    /**
     * Helper class to provide a concrete implementation of RegularTimePeriod for testing.
     */
    private static class SecondRevised extends RegularTimePeriod {
        private final Calendar cal;

        public SecondRevised(Calendar cal) {
            this.cal = cal;
        }

        @Override
        public int getPeriodIncrement() {
            return 1;
        }

        @Override
        public int getPeriodIncrementSign() {
            return 1;
        }

        @Override
        public RegularTimePeriod nextPeriod() {
            Calendar next = (Calendar) cal.clone();
            next.add(Calendar.SECOND, 1);
            return new SecondRevised(next);
        }

        @Override
        public int getPeriodOfYear() {
            return 0;
        }

        @Override
        public int getPeriodOfMonth() {
            return 0;
        }

        @Override
        public int getPeriodOfDay() {
            return 0;
        }

        @Override
        public int getPeriodOfWeek() {
            return 0;
        }

        @Override
        public int getPeriodOfDayMillis() {
            return 0;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj instanceof SecondRevised) {
                return ((SecondRevised) obj).cal.equals(this.cal);
            }
            return false;
        }

        @Override
        public int compareTo(Object o) {
            if (o instanceof SecondRevised) {
                return this.cal.compareTo(((SecondRevised) o).cal);
            }
            return -1;
        }

        @Override
        public int hashCode() {
            return cal.hashCode();
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullStart() throws CloneNotSupportedException {
        series.createCopy(null, endPeriod);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullEnd() throws CloneNotSupportedException {
        series.createCopy(startPeriod, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartAfterEnd() throws CloneNotSupportedException {
        // endPeriod is after startPeriod, so swap them to trigger exception
        series.createCopy(endPeriod, startPeriod);
    }

    @Test
    public void testCreateCopyEmptyRangeDueToHardcodedTrue() throws CloneNotSupportedException {
        // Because of the 'if (true)' block in the source, emptyRange is always true.
        // This tests the branch: if (emptyRange) { copy.data = new ArrayList(); return copy; }

        TimeSeries copy = series.createCopy(startPeriod, endPeriod);

        assertNotNull(copy);
        assertEquals("Copy should be a different instance", false, copy == series);
        assertEquals("Copy should be empty due to if(true) logic", 0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyWithOutOfBoundsStart() throws CloneNotSupportedException {
        // Create a period far in the past to ensure getIndex returns < 0
        RegularTimePeriod wayPast = new SecondRevised(new GregorianCalendar(1900, 0, 1));

        // This triggers: startIndex < 0 -> startIndex = -(startIndex + 1)
        // and the 'if (true)' still forces emptyRange = true.
        TimeSeries copy = series.createCopy(wayPast, endPeriod);

        assertNotNull(copy);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyWithOutOfBoundsEnd() throws CloneNotSupportedException {
        // Create a period far in the future
        RegularTimePeriod wayFuture = new SecondRevised(new GregorianCalendar(2100, 0, 1));

        // This triggers: endIndex < 0 -> endIndex = -(endIndex + 1) -> endIndex - 1
        // and the 'if (true)' still forces emptyRange = true.
        TimeSeries copy = series.createCopy(startPeriod, wayFuture);

        assertNotNull(copy);
        assertEquals(0, copy.getItemCount());
    }
}
